    { [f.actor]: [DeathCause.Poison] },
    new Set(),
    new Set([f.actor]),
    () => {
      trace.push("world");
      return f.world;
    },
    () => {
      trace.push("protect");
      expect(f.binding.resolved).toBe(true);
      return true;
    },
  );
  expect(blocked?.kind).toBe("blocked");
  expect(trace).toEqual(["world", "protect"]);
  expect(f.binding.resolved).toBe(true);
  expect(f.binding.applied).toBe(false);
  expect(f.targetLife.alive).toBe(true);
  expect(
    attemptCharmTrigger(
      f.binding,
      { [f.actor]: [DeathCause.Poison] },
      new Set(),
      new Set([f.actor]),
      () => f.world,
      () => false,
    ),
  ).toBeNull();
});

