    new Set([f.actor, f.target]),
    () => f.world,
    () => false,
  );
  expect(claim?.kind).toBe("claimed");
  if (!claim || claim.kind !== "claimed") throw new Error("fixture_claim_missing");
  expect(commitCharmDeath(f.world, { ...claim })).toBeNull();
